function gather(fn) {
  return function next(...args) {
    if (args.length >= fn.length) return fn(...args);
    return (...more) => next(...args, ...more);
  };
}

function order(table, dish, drink) {
  return `${table}: ${dish} + ${drink}`;
}

const atFive = order.bind(null, 5);
console.log(atFive.length);
console.log(gather(atFive)("soup")("tea"));

const early = gather((table, dish = "bread", drink) => `${table}: ${dish}`);
console.log(early(3));
